# -*- coding: utf-8 -*-
"""أدوات مبيعات وتسويق إضافية (6)."""
from biz_tools import F, S, add, CATS, T
PD="const sum=a=>a.reduce((s,x)=>s+x,0);const pct=(a,b)=>b?a/b*100:0;const dd=(a,b)=>{const x=new Date(a),y=new Date(b);return isNaN(x)||isNaN(y)?0:Math.round((y-x)/864e5)};"

add('sales-pipeline-forecaster','sales','🧭','محلل خط الصفقات وتوقع المبيعات (Pipeline)','ارفع قائمة الفرص لتحصل على التوقع الموزون حسب الاحتمال، وتحليل المراحل والمندوبين، وتنبيهات الصفقات الراكدة والمتأخرة.',
 [F('d','الفرص (عميل | مرحلة | قيمة | احتمال % | تاريخ الإغلاق المتوقع | مندوب | آخر نشاط)','textarea','شركة الرياض | تفاوض | 120000 | 60 | 2026-12-10 | أحمد | 2026-11-20\nمؤسسة النور | عرض سعر | 45000 | 40 | 2026-12-20 | سارة | 2026-11-05\nمجموعة الخليج | تأهيل | 300000 | 20 | 2027-01-30 | أحمد | 2026-10-01\nمتجر الأفق | إغلاق | 18000 | 90 | 2026-11-30 | خالد | 2026-11-25\nشركة المدار | تفاوض | 80000 | 55 | 2026-11-15 | سارة | 2026-11-10\nمصنع الشرق | عرض سعر | 150000 | 35 | 2026-12-28 | خالد | 2026-11-22',r=7),
  F('t','تاريخ اليوم','date','2026-11-26'),F('g','هدف المبيعات للفترة','n',400000),F('st','عدد الأيام بلا نشاط لاعتبار الصفقة راكدة','n',14)],
 r'''function compute(v){'''+PD+r'''
const R=lines(v.d).map(x=>({c:x[0],s:x[1],v:num(x[2]),p:num(String(x[3]).replace('%',''))/100,e:x[4],o:x[5],a:x[6]})).filter(x=>x.v>0);R.forEach(x=>{x.w=x.v*x.p;x.idle=x.a?dd(x.a,v.t):0;x.late=x.e&&dd(x.e,v.t)>0;});
const tot=sum(R.map(x=>x.v)),wt=sum(R.map(x=>x.w)),best=sum(R.filter(x=>x.p>=.5).map(x=>x.v));
const grp=k=>{const o={};R.forEach(x=>{const g=o[x[k]]=o[x[k]]||{n:0,v:0,w:0};g.n++;g.v+=x.v;g.w+=x.w});return o};
const st=grp('s'),ow=grp('o');
const sr=Object.keys(st).map(k=>[k,st[k].n,f(st[k].v,0),f(st[k].w,0),f(pct(st[k].w,wt),1)+'%']);
const or=Object.keys(ow).sort((a,b)=>ow[b].w-ow[a].w).map(k=>[k,ow[k].n,f(ow[k].v,0),f(ow[k].w,0)]);
const stale=R.filter(x=>x.idle>=v.st||x.late);
const gap=Math.max(0,v.g-wt),cov=v.g?tot/v.g:0;
return kpis([kpi('إجمالي الخط',f(tot,0)),kpi('التوقع الموزون',f(wt,0),wt>=v.g?'good':'bad'),kpi('الهدف',f(v.g,0)),kpi('الفجوة',f(gap,0),gap?'bad':'good'),kpi('تغطية الخط للهدف',f(cov,1)+'x',cov>=3?'good':'bad'),kpi('صفقات راكدة/متأخرة',stale.length,stale.length?'bad':'good')])
+'<h4>حسب المرحلة</h4>'+tbl(['المرحلة','عدد','القيمة','الموزونة','حصة'],sr)+'<h4>حسب المندوب</h4>'+tbl(['المندوب','عدد','القيمة','الموزونة'],or)
+'<h4>الصفقات بالتفصيل</h4>'+tbl(['العميل','المرحلة','القيمة','الاحتمال','الموزونة','الإغلاق المتوقع','المندوب','أيام بلا نشاط','تنبيه'],R.sort((a,b)=>b.w-a.w).map(x=>[x.c,x.s,f(x.v,0),f(x.p*100,0)+'%',f(x.w,0),x.e,x.o,x.idle,x.late?'⛔ تأخر تاريخ الإغلاق':x.idle>=v.st?'⚠️ راكدة':'—']))
+rec([gap>0?'الفجوة '+f(gap,0)+' ريال: تحتاج خطًا إضافيًا نحو '+f(gap/Math.max(.1,wt/Math.max(1,tot)),0)+' ريال بحسب متوسط الاحتمال الحالي.':'التوقع الموزون يغطي الهدف.',cov<3?'القاعدة المعتادة: خط صفقات بثلاثة أضعاف الهدف؛ تغطيتك '+f(cov,1)+'x فزد التأهيل.':'تغطية الخط جيدة.',stale.length?'حدّث '+stale.length+' صفقة راكدة أو متأخرة أو أغلقها بصدق.':'لا صفقات راكدة.','قارن احتمالات المراحل بنسب الإغلاق التاريخية الفعلية لا بالتقدير الشخصي.'])
+aiOut('حلّل خط الصفقات واقترح خطوات لسد الفجوة: '+JSON.stringify({tot:tot,wt:wt,goal:v.g,stale:stale.map(x=>x.c)}))}''')

add('sales-target-planner','sales','🎯','مخطط هدف المبيعات العكسي (من الهدف إلى الاتصالات)','أدخل هدف الإيراد ومتوسط الصفقة ونسب التحويل لتعرف عدد الصفقات والعروض والاجتماعات والاتصالات المطلوبة يوميًا وعدد المندوبين اللازم.',
 [F('g','هدف الإيراد للفترة','n',600000),F('a','متوسط قيمة الصفقة','n',15000),F('w','نسبة الإغلاق من العروض %','n',25),F('q','نسبة تحويل الاجتماعات إلى عروض %','n',50),F('m','نسبة تحويل الاتصالات إلى اجتماعات %','n',10),F('d','أيام العمل في الفترة','n',22),F('c','اتصالات يومية يستطيعها المندوب','n',30),F('r','الإيراد الحالي لكل مندوب في الفترة','n',90000)],
 r'''function compute(v){const deals=Math.ceil(v.g/Math.max(1,v.a)),offers=Math.ceil(deals/Math.max(.01,v.w/100)),meets=Math.ceil(offers/Math.max(.01,v.q/100)),calls=Math.ceil(meets/Math.max(.01,v.m/100)),perDay=calls/Math.max(1,v.d),reps=Math.ceil(perDay/Math.max(1,v.c)),repsRev=Math.ceil(v.g/Math.max(1,v.r));
const steps=[['صفقات مغلقة',deals,'—'],['عروض أسعار',offers,f(offers/Math.max(1,v.d),1)+' يوميًا'],['اجتماعات/عروض تقديمية',meets,f(meets/Math.max(1,v.d),1)+' يوميًا'],['اتصالات/تواصل',calls,f(perDay,1)+' يوميًا']];
const sc=[0.8,1,1.2,1.5].map(k=>{const g=v.g*k;const c=Math.ceil(g/Math.max(1,v.a)/Math.max(.01,v.w/100)/Math.max(.01,v.q/100)/Math.max(.01,v.m/100));return[f(k*100,0)+'%',f(g,0),Math.ceil(g/Math.max(1,v.a)),c,f(c/Math.max(1,v.d),0)]});
return kpis([kpi('الصفقات المطلوبة',f(deals,0)),kpi('اتصالات يوميًا',f(perDay,0)),kpi('مندوبون (حسب الاتصالات)',reps),kpi('مندوبون (حسب الإيراد)',repsRev)])
+'<h4>قمع المبيعات العكسي</h4>'+tbl(['المرحلة','العدد المطلوب','المعدل'],steps)+'<h4>سيناريوهات الهدف</h4>'+tbl(['من الهدف','الإيراد','صفقات','اتصالات','اتصالات يوميًا'],sc)
+rec(['أضعف حلقة في القمع هي أكبر رافعة: رفع نسبة الإغلاق 5 نقاط يخفض الجهد أكثر من زيادة الاتصالات.','متوسط الصفقة الأعلى يقلل الحجم المطلوب؛ فكّر في حزم وبيع إضافي.','قارن عدد المندوبين من الزاويتين: الأكبر هو الأواقعي.'])}''')

add('discount-breakeven-calculator','sales','🏷️','حاسبة أثر الخصم ونقطة التعادل','احسب الزيادة اللازمة في المبيعات حتى يعوّض الخصم انخفاض الهامش، وقارن عدة نسب خصم وأثرها على الربح.',
 [F('p','سعر البيع الحالي','n',100),F('c','تكلفة الوحدة','n',60),F('q','الكمية الشهرية الحالية','n',1000),F('dl','نسب الخصم المقارنة % (مفصولة بفواصل)','t','5,10,15,20,30'),F('e','الزيادة المتوقعة في الكمية لكل 1% خصم (%)','n',2)],
 r'''function compute(v){const m0=v.p-v.c,pr0=m0*v.q;const L=String(v.dl).split(/[,،\s]+/).map(Number).filter(x=>x>0&&x<100);
const rows=L.map(d=>{const p=v.p*(1-d/100),m=p-v.c,be=m>0?(m0/m-1)*100:Infinity,q=v.q*(1+v.e*d/100),pr=m*q;return[d+'%',f(p),f(m),f(m/p*100,1)+'%',m>0?f(be,0)+'%':'لا يتعادل',f(q,0),f(pr,0),'<b style="color:'+(pr>=pr0?'#16a34a':'#dc2626')+'">'+f(pr-pr0,0)+'</b>']});
const maxD=(1-v.c/v.p)*100;
return kpis([kpi('الهامش الحالي',f(m0)),kpi('هامش %',f(m0/v.p*100,1)+'%'),kpi('الربح الشهري الحالي',f(pr0,0)),kpi('أقصى خصم قبل الخسارة',f(maxD,1)+'%','bad')])
+'<h4>مقارنة نسب الخصم</h4>'+tbl(['الخصم','السعر','هامش الوحدة','هامش %','زيادة المبيعات للتعادل','الكمية المتوقعة','الربح المتوقع','الفرق عن الحالي'],rows)
+rec(['خصم 10% على هامش 40% يتطلب زيادة مبيعات نحو 33% ليتعادل الربح — لا تُخصم دون خطة حجم.','إن كان الخصم مبررًا فاربطه بمدة وكمية أو حزمة بدل خصم مفتوح.','الأرقام المتوقعة افتراضية: اختبرها على عيّنة صغيرة قبل التعميم.'])}''')

add('churn-retention-calculator','marketing','🔄','حاسبة معدل الفقد والاحتفاظ وقيمة تحسينه','احسب معدل فقد العملاء، العمر المتوقع، قيمة العميل LTV، وكم يضيف تحسين الاحتفاظ بنسبة معينة إلى الإيراد والقيمة.',
 [F('s','عملاء بداية الفترة','n',1000),F('n','عملاء جدد خلال الفترة','n',150),F('e','عملاء نهاية الفترة','n',1020),F('a','متوسط الإيراد الشهري لكل عميل','n',120),F('g','هامش الربح %','n',55),F('i','تحسين الاحتفاظ المستهدف (نقاط %)','n',5)],
 r'''function compute(v){const lost=v.s+v.n-v.e,ch=lost/Math.max(1,v.s)*100,ret=100-ch,life=ch>0?100/ch:Infinity,ltv=ch>0?v.a*v.g/100*life:0;
const ch2=Math.max(.1,ch-v.i),life2=100/ch2,ltv2=v.a*v.g/100*life2,gain=(ltv2-ltv)*v.e;
const rows=[0,1,2,3,5,8].map(k=>{const c=Math.max(.1,ch-k);return['−'+k+' نقاط',f(c,1)+'%',f(100/c,1),f(v.a*v.g/100*100/c,0)]});
return kpis([kpi('عملاء مفقودون',f(lost,0),'bad'),kpi('معدل الفقد',f(ch,1)+'%',ch>10?'bad':'good'),kpi('الاحتفاظ',f(ret,1)+'%'),kpi('العمر المتوقع (فترات)',isFinite(life)?f(life,1):'—'),kpi('LTV (ربح)',f(ltv,0)),kpi('قيمة تحسين '+v.i+' نقاط',f(gain,0),'good')])
+'<h4>أثر خفض الفقد</h4>'+tbl(['التحسين','معدل الفقد','العمر المتوقع','LTV'],rows)
+rec(['خفض الفقد أرخص غالبًا من اكتساب عميل جديد: ابدأ بتحليل أسباب الإلغاء.','راقب الفقد في أول 30–90 يومًا؛ فهو الأعلى عادة وأسهل للإصلاح بتجربة البداية.','فعّل حملات استرجاع للعملاء الخاملين قبل فقدهم.'])}''')

add('ad-budget-planner','marketing','💸','مخطط الميزانية الإعلانية وتوزيعها على القنوات','حدد هدف الإيراد وROAS المتوقع لكل قناة، فيحسب الميزانية المطلوبة وتوزيعها وعدد الطلبات والعملاء المتوقع، مع اختبار حساسية الأداء.',
 [F('g','هدف الإيراد من الإعلانات','n',300000),F('a','متوسط قيمة الطلب','n',250),F('ch','القنوات (قناة | ROAS متوقع | حصة %)','textarea','Meta | 3.5 | 40\nGoogle بحث | 5 | 25\nTikTok | 2.5 | 20\nسناب | 2 | 15',r=5),F('cv','نسبة التحويل المتوقعة %','n',2.5),F('cpc','سعر النقرة التقريبي','n',1.2)],
 r'''function compute(v){'''+PD+r'''
const C=lines(v.ch).map(x=>({n:x[0],r:num(x[1]),s:num(String(x[2]).replace('%',''))})).filter(x=>x.r>0);const ts=sum(C.map(x=>x.s))||1;C.forEach(x=>{x.sh=x.s/ts;x.rev=v.g*x.sh;x.b=x.rev/x.r;x.o=x.rev/Math.max(1,v.a)});
const bt=sum(C.map(x=>x.b)),ro=bt?v.g/bt:0,ord=sum(C.map(x=>x.o)),clicks=ord/Math.max(.1,v.cv/100),cpa=ord?bt/ord:0;
const sens=[.8,.9,1,1.1,1.2].map(k=>{const rev=v.g*k;return[f(k*100,0)+'%',f(rev,0),f(bt,0),f(bt?rev/bt:0)+'x']});
return kpis([kpi('الميزانية المطلوبة',f(bt,0),'good'),kpi('ROAS المختلط',f(ro)+'x'),kpi('طلبات متوقعة',f(ord,0)),kpi('تكلفة الطلب CPA',f(cpa)),kpi('نقرات لازمة',f(clicks,0)),kpi('ميزانية النقرات (CPC)',f(clicks*v.cpc,0))])
+'<h4>توزيع الميزانية</h4>'+tbl(['القناة','حصة الإيراد','الإيراد','ROAS المتوقع','الميزانية','طلبات'],C.map(x=>[x.n,f(x.sh*100,0)+'%',f(x.rev,0),f(x.r)+'x',f(x.b,0),f(x.o,0)]))
+'<h4>حساسية الأداء (إن اختلف الإيراد الفعلي والميزانية ثابتة)</h4>'+tbl(['تحقق الهدف','الإيراد','الميزانية','ROAS الفعلي'],sens)
+rec(['خصص 10–20% من الميزانية للاختبار الإبداعي.','راجع ROAS أسبوعيًا ووسّع تدريجيًا في القنوات التي تتجاوز المتوقع.','ROAS المقبول يعتمد على هامشك: عند هامش 40% يلزم ROAS أعلى من 2.5 ليتعادل الربح.'])}''')

add('sales-rep-scorecard','sales','🏅','بطاقة تقييم أداء المندوبين','ارفع أداء المندوبين (مبيعات، هدف، زيارات، عروض، عملاء جدد) لتحصل على تقييم موزون وترتيب وتوصيات لكل مندوب.',
 [F('d','الأداء (مندوب | مبيعات | هدف | زيارات | عروض | عملاء جدد | مرتجعات)','textarea','أحمد | 210000 | 200000 | 85 | 40 | 12 | 5000\nسارة | 160000 | 180000 | 110 | 55 | 9 | 2000\nخالد | 95000 | 150000 | 60 | 22 | 4 | 9000\nمنى | 240000 | 200000 | 70 | 35 | 15 | 1000\nيوسف | 130000 | 140000 | 95 | 30 | 6 | 3000',r=6),F('w1','وزن تحقيق الهدف %','n',50),F('w2','وزن النشاط (زيارات وعروض) %','n',20),F('w3','وزن العملاء الجدد %','n',20),F('w4','وزن جودة المبيعات (قلة المرتجعات) %','n',10)],
 r'''function compute(v){'''+PD+r'''
const R=lines(v.d).map(x=>({n:x[0],s:num(x[1]),t:num(x[2]),v:num(x[3]),o:num(x[4]),c:num(x[5]),r:num(x[6])})).filter(x=>x.n);
const mx=k=>Math.max(1,...R.map(x=>x[k])),W=v.w1+v.w2+v.w3+v.w4||1;
R.forEach(x=>{x.a=pct(x.s,x.t);x.act=((x.v/mx('v'))+(x.o/mx('o')))/2*100;x.nw=x.c/mx('c')*100;x.q=100-Math.min(100,pct(x.r,x.s)*5);x.sc=(Math.min(150,x.a)/1.5*v.w1+x.act*v.w2+x.nw*v.w3+x.q*v.w4)/W;x.cv=pct(x.o,x.v)});
const rows=R.slice().sort((a,b)=>b.sc-a.sc).map((x,i)=>[i+1,x.n,f(x.s,0),f(x.a,0)+'%',x.v,x.o,x.c,f(pct(x.r,x.s),1)+'%','<b>'+f(x.sc,0)+'</b>',x.sc>=75?'🟢 ممتاز':x.sc>=55?'🟡 جيد':'🔴 يحتاج دعمًا']);
const tot=sum(R.map(x=>x.s)),tt=sum(R.map(x=>x.t));
const tips=R.map(x=>x.a<80&&x.act>60?x.n+': نشاط جيد وتحقيق ضعيف → درّبه على الإغلاق والتسعير.':x.a>=100&&x.act<50?x.n+': يحقق بنشاط قليل → ركّز على الحسابات الكبرى وسعة أكبر.':x.r/Math.max(1,x.s)>.05?x.n+': مرتجعات مرتفعة → راجع وعوده للعميل.':null).filter(Boolean);
return kpis([kpi('إجمالي المبيعات',f(tot,0)),kpi('تحقيق الهدف',f(pct(tot,tt),0)+'%',tot>=tt?'good':'bad'),kpi('أفضل مندوب',rows[0]?rows[0][1]:'—'),kpi('متوسط التقييم',f(sum(R.map(x=>x.sc))/Math.max(1,R.length),0))])
+'<h4>الترتيب والتقييم</h4>'+tbl(['#','المندوب','المبيعات','تحقيق الهدف','زيارات','عروض','عملاء جدد','مرتجعات %','التقييم','الحالة'],rows)
+'<h4>تحويل الزيارات إلى عروض</h4>'+tbl(['المندوب','زيارات','عروض','نسبة التحويل'],R.map(x=>[x.n,x.v,x.o,f(x.cv,0)+'%']))
+rec(tips.length?tips:['أداء متوازن: ركّز على رفع المتوسط بالتدريب.','اربط الحوافز بنفس المعايير الموزونة لتوجيه السلوك.'])}''')
